from pathlib import Path


def patch(path, old, new, count=1):
    p = Path(path)
    src = p.read_text()
    n = src.count(old)
    if n != count:
        raise RuntimeError(f'{path}: expected {count} matches, found {n} for {old[:110]!r}')
    p.write_text(src.replace(old, new, count))

